/**
 * Production server for the public site: the product page at /, and the privacy, terms and support
 * pages the App Store listing links to. Nothing else is served. The iPhone app is built and signed
 * through the App Store launch flow, not downloaded from here, so the Expo Go manifest and bundles
 * stay off the public domain (they would let anyone run the app outside the App Store).
 *
 * Zero external dependencies: uses only Node.js built-ins (http, fs, path).
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

// Generated by `pnpm run legal:pages` from the same text the app shows.
const PAGES_ROOT = path.resolve(__dirname, 'pages');
const PAGES = { '': 'index.html', '/privacy': 'privacy.html', '/terms': 'terms.html', '/support': 'support.html' };
const basePath = (process.env.BASE_PATH || '/').replace(/\/+$/, '');

function send(res, status, type, body) {
  res.writeHead(status, { 'content-type': type, 'cache-control': 'public, max-age=300', 'x-content-type-options': 'nosniff' });
  res.end(body);
}

const pages = Object.fromEntries(Object.entries(PAGES).map(([route, file]) => [route, fs.readFileSync(path.join(PAGES_ROOT, file))]));
const notFound = 'Not found. See /support for help with the app.';

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '/', 'http://localhost');
  let pathname = url.pathname;
  if (basePath && pathname.startsWith(basePath)) pathname = pathname.slice(basePath.length) || '/';
  // The workspace preview checks this route to see that the server is up.
  if (pathname === '/status') return send(res, 200, 'text/plain; charset=utf-8', 'ok');
  if (req.method !== 'GET' && req.method !== 'HEAD') return send(res, 405, 'text/plain; charset=utf-8', 'Method not allowed');
  const route = pathname.replace(/\/+$/, '').replace(/\.html$/, '').replace(/^\/index$/, '');
  const page = pages[route];
  if (page) return send(res, 200, 'text/html; charset=utf-8', req.method === 'HEAD' ? undefined : page);
  send(res, 404, 'text/plain; charset=utf-8', notFound);
});

const port = parseInt(process.env.PORT || '3000', 10);
server.listen(port, '0.0.0.0', () => {
  console.log(`Serving the product and legal pages on port ${port}`);
});
